  // =====================================================================================
  //  BOUNCE OUT! race set (show pool) — long, interactive, a real challenge
  // =====================================================================================
  const tileGrid = (k, h, C2, ROWS, S, z0, branch, tints, firstTile) => {
    const rnd = h.rng, real = new Set(), order = [];
    let col = 1 + Math.floor(rnd() * (C2 - 2)), ti = firstTile;
    for (let r = 0; r < ROWS; r++) {
      real.add(r + ":" + col); order.push([col, r]);
      if (r < ROWS - 1) {
        let nc = col + (rnd() < branch ? (rnd() < 0.5 ? -2 : 2) : Math.floor(rnd() * 3) - 1);
        nc = Math.max(0, Math.min(C2 - 1, nc));
        while (col !== nc) { col += Math.sign(nc - col); real.add(r + ":" + col); order.push([col, r]); }   // only orthogonal steps
      }
    }
    const xc = (c) => (c - (C2 - 1) / 2) * S;
    for (let r = 0; r < ROWS; r++) for (let c = 0; c < C2; c++) {
      const isReal = real.has(r + ":" + c);
      k.box(xc(c), z0 - r * S, S, S, 0, 0.8, Object.assign({ c: tints[(r + c) % tints.length], look: "tile", floor: 1 }, isReal ? {} : { tile: ti++, step: 1 }), true);
    }
    for (const [c, r] of order) k.wp(xc(c), 0, z0 - r * S);
    return { ti, zA: z0 + S / 2, zB: z0 - (ROWS - 1) * S - S / 2 };
  };
  const pusherBox = (k, x, z, top, w, c, amp, per, ph, axis) => k.box(x, z, w, 1.2, top + 1.6, 1.6, { c, look: "pusher", move: sway(amp, per, ph, axis || "x") }, true);

  // 1. SLIME TOWER — climb a pastel tower while pink slime rises behind you (~270 m, 9 sections)
