    pad(5, 10);
    ss(12, 3.5, 0.27, [-3.2, 3.2]);
    c = pad(6, 14); pusherBox(k, 0, c, 0, 3, "#ff8fc7", 5, 2.4, 0);
    ss(22, 4, 0.22, [0]);
    c = pad(7, 14); k.cp(0, 0, c, 6);
    for (let i = 0; i < 3; i++) ss(10, 3.6, 0.28, [0]);
    const fz = z - 1 - 6;
    k.box(0, fz, 16, 12, 0, 2, { c: "#ffd166", pat: "checker" });
    k.finish(0, fz + 2, 16, -0.6);
    for (let i = 0; i < 14; i++) k.decor(i % 4 === 3 ? "cloudpuff" : "balloon", (i % 2 ? 1 : -1) * (13 + (i % 3) * 6), -2 + (i % 3) * 3, -10 - i * 16, 1.4 + (i % 4 === 3 ? 1 : 0), i, cols[i % 5]);
