    [-144, -156, -168, -178].forEach((zz, i) => { k.doorRow(zz, 22, 6, 2, 1.6, h); castle(zz, 22, 1.6); if (i < 3) for (let j = 0; j < 2; j++) slider(zz - 6, 1.6, i + 4, j); });
    k.cp(0, 1.6, -138, 10); k.cp(0, 1.6, -162, 10);
