app.get("/", (_, res) => res.type("html").send(PAGE));
app.get("/health", (_, res) => res.json({ ok: true, rooms: rooms.size, ver: SERVER_VER, bots: true }));

const PORT = process.env.PORT || 3000;
const SERVER_VER = "2026-11-27-bots";
const TICK = 1000 / 60;
const PUBLIC_CODE = "OPEN";
const rooms = new Map();
const safeCode = (s) => String(s || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6);
function newCode() {
  const A = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  for (;;) { let c = ""; for (let i = 0; i < 4; i++) c += A[Math.floor(Math.random() * A.length)]; if (!rooms.has(c)) return c; }
}
// ---- player profiles (unlock progress + saved look), keyed by a client token, persisted to disk ----
const PROFILE_FILE = process.env.NB_PROFILES || path.join(__dirname, "profiles.json");
let profiles = {};
try { profiles = JSON.parse(fs.readFileSync(PROFILE_FILE, "utf8")) || {}; } catch (e) { profiles = {}; }
let profDirty = false;
const safeToken = (t) => String(t || "").replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 40);
function profileFor(token) {
  if (!token) return { played: 0, wins: 0 };
  if (!profiles[token]) { profiles[token] = { played: 0, wins: 0 }; profDirty = true; }
  return profiles[token];
}
setInterval(() => { if (!profDirty) return; profDirty = false; fs.writeFile(PROFILE_FILE, JSON.stringify(profiles), () => {}); }, 5000);

function makeRoom(code) {
  const r = new Room(code, { emit: (ev, data) => io.to(code).emit(ev, data), onEmpty: () => rooms.delete(code), onProfile: () => { profDirty = true; } });
  r.bots = makeBots(r, code.charCodeAt(0) * 131 + Date.now());
  rooms.set(code, r);
  return r;
}

io.on("connection", (socket) => {
  let room = null;
  socket.on("pingt", (t, cb) => { if (typeof cb === "function") cb(Date.now()); });

  socket.on("join", (data, cb) => {
    if (typeof cb !== "function" || room) return;
    data = Object.assign({}, data, { bot: false });
    let code = safeCode(data.code);
    if (data.create) code = newCode();
    if (!code) code = PUBLIC_CODE;
    let r = rooms.get(code);
    if (!r) {
      if (!data.create && code !== PUBLIC_CODE) return cb({ ok: false, error: "그 방 코드를 찾을 수 없어요." });
      r = makeRoom(code);
    }
    // a full lobby makes room for a real player by dropping one bot
    if (r.players.size >= C.MAX_PLAYERS && r.phase === "lobby" && r.bots.count() > 0) r.bots.setBots(r.bots.count() - 1);
    if (r.players.size >= C.MAX_PLAYERS) return cb({ ok: false, error: "방이 가득 찼어요. (최대 8명)" });
    room = r;
    socket.join(r.code);
    const token = safeToken(data.token);
    const prof = profileFor(token);
    data.prof = prof;
    if (!data.look && prof.look) data.look = prof.look;
    const p = r.addPlayer(socket.id, data);
    if (token) { prof.look = p.look; profDirty = true; }
    socket.data.token = token;
    cb({ ok: true, id: p.id, code: r.code, ver: SERVER_VER, prof: { played: prof.played, wins: prof.wins } });
  });

  socket.on("in", (arr) => { if (room) room.handleInput(socket.id, arr); });
  socket.on("look", (look) => {
    if (!room || !look || typeof look !== "object") return;
    room.setLook(socket.id, look);
    const p = room.players.get(socket.id), tk = socket.data.token;
    if (p && tk && profiles[tk]) { profiles[tk].look = p.look; profDirty = true; }
  });
  socket.on("start", () => { if (room) room.startShow(socket.id); });
  socket.on("endnow", () => { if (room) room.hostEnd(socket.id); });
  socket.on("skip", () => { if (room) room.hostSkip(socket.id); });
  socket.on("mode", (m) => { if (room) room.setMode(socket.id, String(m)); });
  socket.on("vote", (m) => { if (room) { room.vote(socket.id, m == null ? null : String(m)); if (room.bots.count()) room.bots.votes(room.host); } });
  socket.on("bots", (n, cb) => {
    const reply = typeof cb === "function" ? cb : () => {};
    if (!room) return reply({ ok: false, error: "방에 들어가 있지 않아요." });
    if (room.host !== socket.id) return reply({ ok: false, error: "방장만 봇을 바꿀 수 있어요." });
    if (room.phase !== "lobby") return reply({ ok: false, error: "로비에서만 봇을 바꿀 수 있어요." });
    if (!Number.isFinite(+n)) return reply({ ok: false });
    room.bots.setBots(+n);
    reply({ ok: true, count: room.bots.count() });
  });
  socket.on("pick", (m) => { if (room) room.hostPick(socket.id, m == null ? null : String(m)); });
  socket.on("events", (on) => { if (room) room.setEvents(socket.id, !!on); });
  socket.on("emote", (k) => {
    if (!room) return;
    const e = ["wave", "laugh", "cry", "heart"].includes(k) ? k : null;
    if (e) room.emit("ev", { k: "emote", id: socket.id, e });
  });
  socket.on("disconnect", () => { if (room) room.removePlayer(socket.id); room = null; });
});

let last = Date.now(), accum = 0;
setInterval(() => {
  const now = Date.now();
  accum += now - last; last = now;
  if (accum > 250) accum = 250;
  while (accum >= TICK) {
    accum -= TICK;
    for (const r of rooms.values()) { r.bots.tick(); r.update(Date.now()); }
  }
}, 4);

server.listen(PORT, () => console.log(`NEON BUMP running on http://localhost:${PORT}`));
